with filtered as (select *, case when quantity >= 8 then 'High' when quantity >= 4 then 'Medium' else 'Low' end as quantity_level, round(unit_price, 1) as unit_price_rounded from order_items where quantity > 5) select id, order_id, product_id, quantity, unit_price, quantity_level, dense_rank() over (partition by order_id, product_id order by unit_price_rounded) as unit_price_rounded_dense_rank, sum(unit_price_rounded) over (partition by product_id order by unit_price, id rows between unbounded preceding and current row) as running_unit_price_rounded, corr(quantity, unit_price) over (partition by product_id, order_id) as corr_quantity_unit_price, avg(unit_price_rounded) over (partition by order_id, product_id order by unit_price, id rows between 3 preceding and current row) as unit_price_rounded_avg_3, sum(unit_price) over (partition by order_id order by unit_price_rounded, id rows between unbounded preceding and current row) as running_unit_price from filtered where unit_price_rounded >= 30
